DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @chain TABLE (
  namespace_id nvarchar(400) COLLATE Latin1_General_100_BIN2,
  declared_id nvarchar(400) COLLATE Latin1_General_100_BIN2,
  declared_application nvarchar(max),
  semantics nvarchar(max),
  prevver bigint,
  changed bit DEFAULT 0,
  PRIMARY KEY (namespace_id, declared_id));
INSERT @chain (namespace_id, declared_id, declared_application) VALUES
 (N'sidefx:capability:execute-governed-model-invocation', N'model-invocation-execution-port', @app_execute_projected_model_provider_attempt),
 (N'sidefx:capability:execute-projected-model-provider-attempt', N'bind-credential-port', @app_bind_credential),
 (N'sidefx:capability:execute-projected-model-provider-attempt', N'normalize-provider-protocol-port', @app_project_protocol),
 (N'sidefx:capability:execute-projected-model-provider-attempt', N'observe-http-port', @app_observe_http),
 (N'sidefx:capability:execute-projected-model-provider-attempt', N'project-provider-protocol-port', @app_project_protocol),
 (N'sidefx:capability:execute-projected-model-provider-attempt', N'project-request-body-port', @app_project_request_body),
 (N'sidefx:capability:obtain-governed-model-response', N'obtain-fallback-model-response-port', @app_execute_governed_model_invocation),
 (N'sidefx:capability:obtain-governed-model-response', N'obtain-governed-model-response-port', @app_execute_governed_model_invocation);

UPDATE c SET semantics=JSON_QUERY(d.definition_json,'$.semantics'),
  prevver=(SELECT pv.port_version_pk FROM model.port_version pv WHERE pv.semantic_object_definition_pk=d.semantic_object_definition_pk)
FROM @chain c
JOIN analysis.v_selected_semantic_definition d
  ON d.estate_model_pk=@estate AND d.object_kind='PORT'
 AND d.namespace_id=c.namespace_id COLLATE Latin1_General_100_BIN2
 AND d.declared_id=c.declared_id COLLATE Latin1_General_100_BIN2;
IF (SELECT COUNT(*) FROM @chain WHERE semantics IS NULL)<>0 THROW 51000,'DECLARED_CHAIN_PORT_NOT_FOUND',1;
IF EXISTS (SELECT 1 FROM @chain WHERE prevver IS NULL) THROW 51000,'DECLARED_CHAIN_PORT_VERSION_MISSING',1;
IF EXISTS (SELECT 1 FROM @chain WHERE JSON_QUERY(semantics,'$.configuration.declaredApplication') IS NULL
  AND ISNULL(JSON_VALUE(semantics,'$.configuration.bindingRef'),N'') NOT LIKE N'%projected/application-binding.node.json')
  THROW 51000,'DECLARED_CHAIN_PORT_DIVERGED',1;

DECLARE @namespace nvarchar(400), @declared nvarchar(400), @semantics nvarchar(max), @application nvarchar(max),
  @prevver bigint, @object bigint, @definition bigint, @digest binary(32), @version bigint, @portpk bigint;
DECLARE chain_cursor CURSOR LOCAL FAST_FORWARD FOR
  SELECT namespace_id, declared_id, semantics, declared_application, prevver FROM @chain WHERE JSON_QUERY(semantics,'$.configuration.declaredApplication') IS NULL
  ORDER BY namespace_id, declared_id;
OPEN chain_cursor;
FETCH NEXT FROM chain_cursor INTO @namespace, @declared, @semantics, @application, @prevver;
WHILE @@FETCH_STATUS=0 BEGIN
  SET @semantics=JSON_MODIFY(@semantics,'$.configuration.declaredApplication',JSON_QUERY(@application));
  SET @semantics=JSON_MODIFY(@semantics,'$.configuration.bindingRef',NULL);
  SET @semantics=JSON_MODIFY(@semantics,'$.configuration.bindingBase',NULL);
  EXEC model.put_semantic_definition 'PORT', @namespace, @declared, @semantics,
    @object OUTPUT, @definition OUTPUT, @digest OUTPUT;
  SET @portpk=(SELECT port_pk FROM model.port WHERE semantic_object_pk=@object);
  IF @portpk IS NULL THROW 51000,'DECLARED_CHAIN_PORT_ROW_MISSING',1;
  SET @version=(SELECT port_version_pk FROM model.port_version WHERE semantic_object_definition_pk=@definition);
  IF @version IS NULL BEGIN
    INSERT model.port_version(port_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,
      port_profile,object_kind,_owner_definition_pk,_canonical_pointer)
    VALUES(@portpk,@object,@definition,@digest,'consumer-interface-authority.v1','PORT',@definition,N'');
    SET @version=SCOPE_IDENTITY();
  END
  UPDATE model.operation_port_invocation SET port_version_pk=@version WHERE port_version_pk=@prevver;
  UPDATE @chain SET changed=1 WHERE namespace_id=@namespace COLLATE Latin1_General_100_BIN2
    AND declared_id=@declared COLLATE Latin1_General_100_BIN2;
  FETCH NEXT FROM chain_cursor INTO @namespace, @declared, @semantics, @application, @prevver;
END
CLOSE chain_cursor;
DEALLOCATE chain_cursor;
GO
