UPDATE r SET semantics=JSON_QUERY(d.definition_json,'$.semantics'),
  prevver=(SELECT pv.port_version_pk FROM model.port_version pv WHERE pv.semantic_object_definition_pk=d.semantic_object_definition_pk)
FROM @retire r
JOIN analysis.v_selected_semantic_definition d
  ON d.estate_model_pk=@estate AND d.object_kind='PORT'
 AND d.namespace_id=r.namespace_id COLLATE Latin1_General_100_BIN2
 AND d.declared_id=r.declared_id COLLATE Latin1_General_100_BIN2;
IF (SELECT COUNT(*) FROM @retire WHERE semantics IS NULL)<>0 THROW 51000,'RETIRED_BINDING_PORT_NOT_FOUND',1;
IF EXISTS (SELECT 1 FROM @retire WHERE prevver IS NULL) THROW 51000,'RETIRED_BINDING_PORT_VERSION_MISSING',1;
IF EXISTS (SELECT 1 FROM @retire WHERE JSON_VALUE(semantics,'$.configuration.bindingRef') IS NOT NULL
  AND JSON_VALUE(semantics,'$.configuration.bindingRef') COLLATE Latin1_General_100_BIN2 <> binding_ref COLLATE Latin1_General_100_BIN2)
  THROW 51000,'RETIRED_BINDING_PORT_DIVERGED',1;

DECLARE @namespace nvarchar(400), @declared nvarchar(400), @semantics nvarchar(max),
  @prevver bigint, @object bigint, @definition bigint, @digest binary(32), @version bigint, @portpk bigint;
DECLARE retire_cursor CURSOR LOCAL FAST_FORWARD FOR
  SELECT namespace_id, declared_id, semantics, prevver FROM @retire WHERE JSON_VALUE(semantics,'$.configuration.bindingRef') IS NOT NULL
  ORDER BY namespace_id, declared_id;
OPEN retire_cursor;
FETCH NEXT FROM retire_cursor INTO @namespace, @declared, @semantics, @prevver;
WHILE @@FETCH_STATUS=0 BEGIN
  SET @semantics=JSON_MODIFY(@semantics,'$.configuration.bindingRef',NULL);
  SET @semantics=JSON_MODIFY(@semantics,'$.configuration.bindingBase',NULL);
  EXEC model.put_semantic_definition 'PORT', @namespace, @declared, @semantics,
    @object OUTPUT, @definition OUTPUT, @digest OUTPUT;
  SET @portpk=(SELECT port_pk FROM model.port WHERE semantic_object_pk=@object);
  IF @portpk IS NULL THROW 51000,'RETIRED_BINDING_PORT_ROW_MISSING',1;
  SET @version=(SELECT port_version_pk FROM model.port_version WHERE semantic_object_definition_pk=@definition);
  IF @version IS NULL BEGIN
    INSERT model.port_version(port_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,
      port_profile,object_kind,_owner_definition_pk,_canonical_pointer)
    VALUES(@portpk,@object,@definition,@digest,'consumer-interface-authority.v1','PORT',@definition,N'');
    SET @version=SCOPE_IDENTITY();
  END
  UPDATE model.operation_port_invocation SET port_version_pk=@version WHERE port_version_pk=@prevver;
  UPDATE @retire SET changed=1 WHERE namespace_id=@namespace COLLATE Latin1_General_100_BIN2
    AND declared_id=@declared COLLATE Latin1_General_100_BIN2;
  FETCH NEXT FROM retire_cursor INTO @namespace, @declared, @semantics, @prevver;
END
CLOSE retire_cursor;
DEALLOCATE retire_cursor;
SELECT '2_retired_rows' AS result_set, (SELECT COUNT(*) FROM @retire WHERE changed=1) AS rows_changed;
GO
-- ============================== VERIFICATION ==============================
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
SELECT '1_declared_chain' AS result_set, d.namespace_id, d.declared_id,
  d.semantic_object_definition_pk AS sod,
  CASE WHEN JSON_QUERY(d.definition_json,'$.semantics.configuration.declaredApplication') IS NULL THEN 0 ELSE 1 END AS declared_application,
  CASE WHEN JSON_VALUE(d.definition_json,'$.semantics.configuration.bindingRef') IS NULL THEN 0 ELSE 1 END AS binding_ref,
  CASE WHEN JSON_QUERY(d.definition_json,'$.semantics.configuration.declaredApplication.nestedApplications') IS NULL THEN 0 ELSE 1 END AS nested_applications,
  JSON_VALUE(d.definition_json,'$.semantics.configuration.bindingDigest') AS binding_digest,
  JSON_VALUE(d.definition_json,'$.semantics.configuration.capabilityAuthorityDigest') AS authority_digest
FROM analysis.v_selected_semantic_definition d
WHERE d.estate_model_pk=@estate AND d.object_kind='PORT'
  AND d.declared_id IN (N'model-invocation-execution-port',N'bind-credential-port',N'normalize-provider-protocol-port',N'observe-http-port',N'project-provider-protocol-port',N'project-request-body-port',N'obtain-fallback-model-response-port',N'obtain-governed-model-response-port')
ORDER BY d.declared_id;
SELECT '3_remaining_binding_refs' AS result_set, COUNT(*) AS count
FROM analysis.v_selected_semantic_definition d
WHERE d.estate_model_pk=@estate AND d.object_kind='PORT'
  AND JSON_VALUE(d.definition_json,'$.semantics.configuration.bindingRef') IS NOT NULL;
COMMIT TRANSACTION;
